private static String substVars(String value, Properties props) {
    StringBuilder buf = new StringBuilder();
    int start = 0;
    int end = value.indexOf("${", start);
    while (end != -1) {
        buf.append(value, start, end);
        int close = value.indexOf("}", end);
        if (close == -1) {
            buf.append(value.substring(end));
            break;
        }
        String expr = value.substring(end + 2, close);
        String replacement = props.getProperty(expr);
        if (replacement != null) {
            buf.append(replacement);
        } else {
            buf.append("${").append(expr).append("}");
        }
        start = close + 1;
        end = value.indexOf("${", start);
    }
    buf.append(value.substring(start));
    return buf.toString();
}
